(()=>{'use strict';const N=true,C='jf-seasonal-overlay',S_ID='jf-seasonal-style',m=new Date().getMonth(),seasons=['winter','spring','summer','autumn'],idx=[11,0,1].includes(m)?0:[2,3,4].includes(m)?1:[5,6,7].includes(m)?2:3,season=N?seasons[idx]:({winter:'summer',spring:'autumn',summer:'winter',autumn:'spring'})[seasons[idx]];
if(!document.getElementById(S_ID)){const s=document.createElement('style');s.id=S_ID;
let css=`#${C}{position:fixed;top:0;left:0;width:100vw;height:100vh;pointer-events:none;z-index:100;overflow:hidden;transition:opacity .4s}#${C}.jf-hidden,body:has(#videoOsdPage:not(.hide)) #${C},body:has(.htmlvideoplayer-container) #${C},body:has(video) #${C}{display:none!important;visibility:hidden!important}.jf-particle{position:absolute;pointer-events:none;user-select:none;will-change:transform,opacity}`;
if(season==='winter')css+=`.jf-particle{background:#fff;border-radius:50%;opacity:.6;box-shadow:0 0 4px #fff;animation:jf-f linear infinite}@keyframes jf-f{0%{transform:translate3d(0,-10vh,0);opacity:0}10%,90%{opacity:.6}100%{transform:translate3d(20px,110vh,0);opacity:0}}`;
else if(season==='spring')css+=`.jf-particle{background:#ffb7c5;border-radius:15px 0 15px 0;opacity:.7;animation:jf-d linear infinite}@keyframes jf-d{0%{transform:translate3d(0,-10vh,0) rotate(0deg);opacity:0}20%,80%{opacity:.8}100%{transform:translate3d(100px,110vh,0) rotate(360deg);opacity:0}}`;
else if(season==='autumn')css+=`.jf-particle{border-radius:2px;opacity:.8;animation:jf-t linear infinite}@keyframes jf-t{0%{transform:translate3d(0,-10vh,0) rotateX(0) rotateY(0);opacity:0}10%,90%{opacity:.8}100%{transform:translate3d(-50px,110vh,0) rotateX(360deg) rotateY(180deg);opacity:0}}`;
else if(season==='summer')css+=`.jf-particle{background:#ffea00;border-radius:50%;box-shadow:0 0 8px 2px rgba(255,234,0,.6);animation:jf-u linear infinite}@keyframes jf-u{0%{transform:translate3d(0,110vh,0) scale(.5);opacity:0}50%{opacity:.6;transform:translate3d(30px,50vh,0) scale(1.2)}100%{transform:translate3d(-30px,-10vh,0) scale(.5);opacity:0}}`;
s.textContent=css;document.head.appendChild(s)}

let cont=document.getElementById(C);if(cont)cont.remove();cont=document.createElement('div');cont.id=C;
const pal=['#e07a5f','#f2cc8f','#d00000','#eb5e28'];
for(let i=0;i<35;i++){const p=document.createElement('div'),z=4+Math.random()*8;p.className='jf-particle';
p.style.cssText=`left:${Math.random()*100}vw;animation-duration:${5+Math.random()*10}s;animation-delay:-${Math.random()*10}s;`+(season==='autumn'?`width:${z+4}px;height:${z+4}px;background-color:${pal[Math.floor(Math.random()*pal.length)]}`:season==='spring'?`width:${z+2}px;height:${z+6}px`:season==='summer'?`width:${z/2}px;height:${z/2}px`:`width:${z}px;height:${z}px`);cont.appendChild(p)}
document.body.appendChild(cont);

const isVid=()=>{if((window.location.hash||'').toLowerCase().includes('/video'))return true;const o=document.getElementById('videoOsdPage');if(o&&!o.classList.contains('hide'))return true;const v=document.querySelector('video');return!!(v&&!v.paused&&v.currentTime>0)},
sync=()=>{const el=document.getElementById(C);if(el)el.classList.toggle('jf-hidden',isVid())};
['hashchange','popstate'].forEach(e=>window.addEventListener(e,sync));
['viewshow','pageshow'].forEach(e=>document.addEventListener(e,sync));
new MutationObserver(sync).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class','style']});
sync();})();
